<?php
require_once __DIR__.'/../config/auth.php';require_role('boss');$pdo=db();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$branch=(int)($_GET['branch']??0);$condition=$branch?' AND b.id=?':'';$args=[$from,$to];if($branch)$args[]=$branch;
$sql="SELECT b.id,b.name,(SELECT COALESCE(SUM(t.total),0) FROM transactions t WHERE t.branch_id=b.id AND t.status='paid' AND DATE(t.created_at) BETWEEN ? AND ?) sales,(SELECT COALESCE(SUM(c.amount),0) FROM cash_movements c WHERE c.branch_id=b.id AND c.type='income' AND c.movement_date BETWEEN ? AND ?) other_income,(SELECT COALESCE(SUM(c.amount),0) FROM cash_movements c WHERE c.branch_id=b.id AND c.type='expense' AND c.movement_date BETWEEN ? AND ?) expense FROM branches b WHERE 1=1$condition ORDER BY b.name";$params=[$from,$to,$from,$to,$from,$to];if($branch)$params[]=$branch;$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$branches=$pdo->query('SELECT id,name FROM branches ORDER BY name')->fetchAll();$pageTitle='Laporan Arus Kas';$active='laporan';include __DIR__.'/../includes/header.php';?>
<section class="card"><form class="filter-row"><label>Dari<input type="date" name="from" value="<?=e($from)?>"></label><label>Sampai<input type="date" name="to" value="<?=e($to)?>"></label><label>Cabang<select name="branch"><option value="0">Semua cabang</option><?php foreach($branches as $b):?><option value="<?=$b['id']?>" <?=$branch===$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></label><button class="btn primary">Terapkan</button></form><p class="muted">Uang masuk = penjualan lunas + pemasukan lain. Arus kas bersih = seluruh uang masuk − pengeluaran.</p><div class="table-wrap"><table class="table"><thead><tr><th>Cabang</th><th>Penjualan</th><th>Pemasukan lain</th><th>Total masuk</th><th>Pengeluaran</th><th>Arus kas bersih</th></tr></thead><tbody><?php foreach($rows as $r):$incoming=$r['sales']+$r['other_income'];?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=rupiah($r['sales'])?></td><td><?=rupiah($r['other_income'])?></td><td><?=rupiah($incoming)?></td><td><?=rupiah($r['expense'])?></td><td><strong><?=rupiah($incoming-$r['expense'])?></strong></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/../includes/footer.php';?>
